function CERTIFY-CAP(M, maxClasses):
    U <- units modulo M ;  n <- |U|
    assert n <= maxClasses          # 2^n enumeration guard
    best <- 0 ; attaining <- {} ; examined <- 0
    for r <- 0 to n:
        for each subset S of U with |S| = r:
            examined <- examined + 1
            total <- 0
            for each target t in {0..n-1}:            # direct simulation
                total <- total + (t in S ? r : n)
            speed <- n / (total / n)
            if speed > best + eps:  best <- speed ; attaining <- {r}
            elif |speed - best| <= eps: attaining <- attaining U {r}
    # cardinality-collapsed pass: one representative per size
    collapsed <- max over r of SIMULATE(n, first r elements)
    return (best, attaining, examined, |best - collapsed| <= eps)

function COMPOSE-BATTERY(dials = [(m_1, K_1), ..., (m_r, K_r)]):
    for i < j: assert gcd(m_i, m_j) = 1        # CRT hypothesis
    M <- product of all m_i
    for i: theta_i <- |K_i| / EULER-PHI(m_i)

    passing <- 0                                # explicit AND over the product
    for u <- 0 to M-1:
        if gcd(u, M) = 1 and (for all i: u mod m_i in K_i):
            passing <- passing + 1
    theta <- passing / EULER-PHI(M)
    assert |theta - product of theta_i| < eps   # densities multiply

    S            <- 1 / (1 - theta + theta^2)
    capacityBits <- sum over i of -log2(theta_i)     # unbounded
    workBits     <- log2(S)                          # <= log2(4/3)
    return (theta, S, capacityBits, workBits,
            workBits / capacityBits, S <= 4/3 + eps)
